#!/usr/bin/env bash
# tests/s10/guest/build.sh <out dir> - the S10 end-to-end check as a real ILP32 guest module.
#
# The demo tree rewritten by dyninit_rewrite.py, compiled for -mabi=ilp32 (ELF32), the table generated by
# mkxctab.py from those ELF32 objects, startup/guest, linked with S5's guest runtime (toolchain/guest:
# crt0.s, runtime.c, guest.specs/guest.ld at 0x10000000) into guest.nso. Run it with
#   python3 -I tests/s5/emu_guest.py <out>/guest.nso --expect "s10 guest: PASS"
# Needs FNVNX_A64 = the fnvnx-a64 prefix (docs/TOOLCHAIN.md).
set -euo pipefail
: "${FNVNX_A64:?set FNVNX_A64 to the fnvnx-a64 prefix}"
OUT=$(mkdir -p "$1" && cd "$1" && pwd)
HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../../.." && pwd)
export FNVNX_TOOLCHAIN="$ROOT/toolchain"
export PATH="$FNVNX_A64/bin:$PATH"
PY="python3 -I"
ARCH="-mabi=ilp32 -march=armv8-a+crc+crypto -mtune=cortex-a57 -fno-pie -ftls-model=local-exec"
CFLAGS="-O2 -Wall -Wextra -Werror -I$ROOT/toolchain/include -I$ROOT/startup/guest"

rm -rf "$OUT/tree"
cp -r "$HERE/../demo/tree" "$OUT/tree"
mkdir -p "$OUT/tree/build" && cp "$HERE/../demo/units.json" "$OUT/tree/build/units.json"
$PY "$ROOT/startup/tools/dyninit_rewrite.py" --units "$OUT/tree/build/units.json" --tree "$OUT/tree"

cd "$OUT"
objs=()
for u in demo_a demo_b demo_a_variant; do
    aarch64-none-elf-g++ $ARCH -std=gnu++17 -O2 -fno-exceptions -fno-rtti -Wall -Werror -I"$OUT/tree/include" \
        -c "$OUT/tree/src/generated/$u.cpp" -o "src_generated_$u.cpp.o"
    objs+=("src_generated_$u.cpp.o")
done
$PY "$ROOT/startup/tools/mkxctab.py" --out xctab.c --addrmap "$HERE/../demo/addrmap.tsv" \
    --group 0x00f40000:0x00f40080 --strict "${objs[@]}"

aarch64-none-elf-gcc $ARCH -c "$ROOT/toolchain/guest/crt0.s" -o crt0.o
aarch64-none-elf-gcc $ARCH $CFLAGS -c "$ROOT/toolchain/guest/runtime.c" -o runtime.o
for src in "$ROOT/startup/guest/xc.c" "$HERE/../demo/storage.c" \
           "$HERE/../demo/e2e_main.c" xctab.c; do
    aarch64-none-elf-gcc $ARCH $CFLAGS -std=c11 -c "$src" -o "$(basename "$src" .c).o"
done
aarch64-none-elf-gcc $ARCH -specs="$ROOT/toolchain/guest/guest.specs" crt0.o runtime.o xc.o storage.o \
    e2e_main.o xctab.o "${objs[@]}" -Wl,-Map,guest.map -o guest.elf
$PY "$ROOT/toolchain/tools/elf2nso.py" guest.elf guest.nso
echo "built $OUT/guest.nso"
